/* Faculty area content, generated from the faculty guides (build_data.py). Do not edit by hand. */
window.PCCN_FACULTY_COMMON = {"rules": "<h1 id=\"must-follow-production-rules\"><strong>1. Must follow — production rules</strong></h1>\n<p>1. <strong>Length:</strong> stay within the cap listed for your video (±2 min). If it runs longer, split it into two parts rather than speeding up.</p>\n<p>2. <strong>Structure:</strong> use the fixed running order in section 2.</p>\n<p>3. <strong>Template:</strong> PCCN slide template only. Title card shows the module number; end card shows “Next: quiz / simulation”.</p>\n<p>4. <strong>Format:</strong> 1080p, 16:9 landscape, MP4. Quiet room, external or headset mic, no echo or fan noise.</p>\n<p>5. <strong>Patient privacy:</strong> no names, faces, bed numbers or hospital IDs. Any clinical photo or clip needs written consent and blurred faces.</p>\n<p>6. <strong>Evidence:</strong> follow current AHA PALS and IAP guidance. Give drug doses per kg with the maximum dose, and use generic drug names only drug dosages should also have standard references.</p>\n<p>7. <strong>No commercial content:</strong> no pharma or device logos, and no product endorsements.</p>\n<p>8. <strong>Language:</strong> British spelling and SI units on slides; speak to the bedside nurse (“you”).</p>\n<p>9. <strong>Quiz alignment:</strong> every Must cover point is taught clearly enough that the module quiz can be answered from the video.</p>\n<p>10. <strong>Delivery:</strong> upload as YouTube <em>Unlisted</em> (or Google Drive “Anyone with the link”). File name format: PCCN_M01_V2_PAT.</p>", "order": "<table>\n<colgroup>\n<col style=\"width: 16%\" />\n<col style=\"width: 83%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>Time</strong></th>\n<th><strong>Segment</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>0:00–0:15</strong></td>\n<td>Title card: PCCN · Module · number · Title · Faculty name</td>\n</tr>\n<tr class=\"even\">\n<td><strong>0:15–1:00</strong></td>\n<td>Bedside case hook: one child, one problem, one question</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>1:00–1:30</strong></td>\n<td>Learning objectives (3 minimum)</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Core</strong></td>\n<td>2–4 teaching chunks. Each chunk ends with a concrete <strong>nurse action</strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Last 1:30</strong></td>\n<td>Return to the case → 3 take-home points → pointer to the quiz or simulation</td>\n</tr>\n<tr class=\"even\">\n<td><strong>0:10</strong></td>\n<td>End card</td>\n</tr>\n</tbody>\n</table>", "style": "<ul>\n<li><p>Picture-in-picture: your face in a corner over the slides keeps nurses watching.</p></li>\n<li><p>One idea per slide, 6 lines maximum. Reveal mnemonics letter by letter.</p></li>\n<li><p>Demonstrate with real equipment used in Indian PICUs rather than describing it.</p></li>\n<li><p>Add one “pause and decide” prompt in the core, then give the answer.</p></li>\n<li><p>Focus on what the nurse does, sees and escalates, not physician decisions.</p></li>\n<li><p>Provide an English subtitle file (.srt) if possible.</p></li>\n</ul>"};
window.PCCN_FACULTY_MODULES = {"01": {"page": "PCCN_Module01_Initial_Assessment.html", "lectures": "<h3 id=\"v1-why-children-are-different-10-min-record-by-mon-19-oct\">V1 Why Children Are Different ≤10 min · record by Mon 19 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Airway: large occiput, large tongue, narrow subglottis, infants breathe through the nose</p></li>\n<li><p>Low respiratory reserve: high O₂ use, soft chest wall, tires quickly</p></li>\n<li><p>Cardiac output depends on heart rate; low blood pressure is a <em>late</em> sign</p></li>\n<li><p>Weight-based dosing and how to estimate weight</p></li>\n<li><p>Heat and glucose loss; family-centred care</p></li>\n</ul>\n<p><strong>Good to know:</strong> length-based tape; adjusting your approach to the child’s developmental stage.</p>\n<h3 id=\"v2-pat-primary-assessment-16-min-record-by-mon-19-oct\">V2 PAT &amp; Primary Assessment ≤16 min · record by Mon 19 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>The 3 sides of the PAT: Appearance (TICLS), Work of Breathing, Circulation to Skin</p></li>\n<li><p>The PAT is done from the doorway in 30–60 seconds, without touching the child</p></li>\n<li><p>From PAT to first impression: stable, respiratory distress or failure, shock, CNS dysfunction, cardiopulmonary failure</p></li>\n<li><p>ABCDE hands-on assessment with normal vital-sign ranges by age</p></li>\n<li><p>Findings that need immediate escalation</p></li>\n</ul>\n<p><strong>Good to know:</strong> SAMPLE history for the secondary assessment; preview of PEWS.</p>\n<h3 id=\"v3-the-direct-approach-14-min-record-by-tue-20-oct\">V3 The DIRECT Approach ≤14 min · record by Tue 20 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>D Detection · I Intervention · R Reassessment · EC Effective Communication · T Transport, with nurse actions at each step</p></li>\n<li><p>Reassess after every intervention and at least every 5 minutes while the child is unstable</p></li>\n<li><p>ISBAR handover and closed-loop communication</p></li>\n<li><p>Checklist for safe transfer within the hospital</p></li>\n</ul>\n<p><strong>Good to know:</strong> overlap with crisis resource management; documenting during a resuscitation.</p>", "sims": "<p><strong>Must follow — every scenario</strong></p>\n<ul>\n<li><p>10–15 minutes long. Case stem → monitor showing vitals that change → 3–5 decision points → feedback on every choice → debrief questions.</p></li>\n<li><p>Every wrong choice shows its consequence on the monitor and a teaching line.</p></li>\n<li><p>Uses the DIRECT approach and the same vital ranges taught in the videos.</p></li>\n<li><p>Faculty provide the storyboard: one row per decision, listing options, the correct answer, the reason, and how the vitals change.</p></li>\n</ul><table><thead><tr><th>Scenario</th><th>Must cover — decision points</th></tr></thead><tbody><tr><td><strong>S1 · M01 Virtual Triage A</strong><br />\n8-month-old, respiratory distress</td><td>PAT impression → A/B checks → oxygen → triage as urgent → ISBAR\ncall</td></tr><tr><td><strong>S2 · M01 Virtual Triage B</strong><br />\n4-year-old, minor injury</td><td>PAT stable → focused assessment → triage down safely → advice to\nfamily</td></tr></tbody></table><p><b>Built so far:</b> the scenario is live in the module as a virtual simulation using the DIRECT steps (impression, intervention, reassessment, communication with parents and team, transfer). Faculty review the options and grades in the verification PDF.</p>", "webinarTitle": "Initial Assessment — \"PICU Layout & Emergency Preparedness\" (90 min)", "webinar": "<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>Crash cart organisation:</strong>\n<ul>\n<li>Drawers in order: Airway, Breathing, Circulation/access, Drugs, Defib/ECG, Miscellaneous.</li>\n<li>Daily seal and expiry checks; restock straight after every code.</li>\n</ul></li>\n<li><strong>The 7 P’s of emergency preparedness:</strong> Staff, System, Supplies, Space, Speak up, Subject, Self.</li>\n<li><strong>SOAPME</strong> before every procedure.</li>\n<li><strong>In-hospital triage levels 1–5.</strong> Mass-casualty and pandemic surge triage only as an introduction.</li>\n<li><strong>Breakout drill:</strong> each room audits a photo of a crash cart (provided) and lists 5 errors. Then each room triages 6 children waiting in the emergency room using PAT and ABCDE.</li>\n</ul>\n<p><strong>Good to know:</strong> the WHO surgical safety checklist evidence; the Hudson River case as a lesson in preparation.</p>", "downloads": [{"label": "Faculty guide · Modules 01–03 (PDF)", "href": "assets/faculty/PCCN_Faculty_Guide_M01-M03.pdf"}, {"label": "Live webinars faculty guide (PDF)", "href": "assets/faculty/PCCN_Live_Webinars_Faculty_Guide_M01-M04_M07.pdf"}, {"label": "Learner study material · Module 01 (PDF)", "href": "assets/pdf/PCCN_Module01_Study_Material.pdf"}]}, "02": {"page": "PCCN_Module02_Respiratory_Support.html", "lectures": "<h3 id=\"v4-respiratory-distress-vs-failure-10-min-record-by-wed-21-oct\">V4 Respiratory Distress vs Failure ≤10 min · record by Wed 21 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Signs of distress: fast breathing, recessions, nasal flaring, grunting, head bobbing</p></li>\n<li><p>Signs of failure: exhaustion, slowing breathing, silent chest, cyanosis, drowsiness</p></li>\n<li><p>The 3 E’s: Effort, Efficacy, Effects</p></li>\n<li><p>Types of problem: upper airway, lower airway, lung tissue, disordered control of breathing</p></li>\n<li><p>When to call for help</p></li>\n</ul>\n<p><strong>Good to know:</strong> basic blood-gas patterns in respiratory failure.</p>\n<h3 id=\"v5-oxygen-delivery-systems-12-min-record-by-wed-21-oct\">V5 Oxygen Delivery Systems ≤12 min · record by Wed 21 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Low-flow vs high-flow devices: nasal prongs, simple mask, non-rebreather mask, with flow rates and approximate FiO₂</p></li>\n<li><p>SpO₂ target 94–98%, unless the child’s condition sets a different target</p></li>\n<li><p>Humidification, and choosing a device by the child’s size and tolerance</p></li>\n<li><p>Escalation ladder and how to wean</p></li>\n</ul>\n<p><strong>Good to know:</strong> how to calculate how long an oxygen cylinder will last; oxygen risks in preterm infants.</p>\n<h3 id=\"v6-bag-mask-ventilation-14-min-record-by-thu-22-oct\">V6 Bag-Mask Ventilation ≤14 min · record by Thu 22 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>When to start; choosing the bag size, and a mask that covers both nose and mouth</p></li>\n<li><p>Head position (neutral for infants, sniffing for older children); C-E grip; two-person technique</p></li>\n<li><p>Rate as per current PALS; watch for chest rise; avoid over-ventilating the child or inflating the stomach</p></li>\n<li><p>Troubleshooting when the chest does not rise</p></li>\n</ul>\n<p><strong>Good to know:</strong> PEEP valve; sizing an oropharyngeal airway.</p>\n<h3 id=\"v7-high-flow-nasal-cannula-hfnc-14-min-record-by-thu-22-oct\">V7 High-Flow Nasal Cannula (HFNC) ≤14 min · record by Thu 22 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>How it works: flushes dead space, gives a PEEP-like effect, delivers heated humidified gas</p></li>\n<li><p>When it is used, how to set it up, and starting flow per your unit protocol</p></li>\n<li><p>Signs it is working within 1–2 hours (HR, RR, SpO₂) and signs it is failing</p></li>\n<li><p>Nursing care: prongs fill less than half of each nostril, skin checks, feeding, positioning</p></li>\n</ul>\n<p><strong>Good to know:</strong> ROX index; using HFNC for apnoeic oxygenation.</p>\n<h3 id=\"v8-the-art-of-nebulisation-10-min-record-by-fri-23-oct\">V8 The Art of Nebulisation ≤10 min · record by Fri 23 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Common drugs and when to use them: salbutamol, ipratropium, adrenaline, hypertonic saline</p></li>\n<li><p>Jet nebuliser vs MDI with spacer; oxygen-driven nebuliser at 6–8 L/min</p></li>\n<li><p>Technique: mask fit and position; a crying child receives less of the drug</p></li>\n<li><p>Monitoring side effects; cleaning and infection control</p></li>\n</ul>\n<p><strong>Good to know:</strong> continuous nebulisation; spacer-and-mask technique in infants.</p>", "sims": "<p><strong>Must follow — every scenario</strong></p>\n<ul>\n<li><p>10–15 minutes long. Case stem → monitor showing vitals that change → 3–5 decision points → feedback on every choice → debrief questions.</p></li>\n<li><p>Every wrong choice shows its consequence on the monitor and a teaching line.</p></li>\n<li><p>Uses the DIRECT approach and the same vital ranges taught in the videos.</p></li>\n<li><p>Faculty provide the storyboard: one row per decision, listing options, the correct answer, the reason, and how the vitals change.</p></li>\n</ul><table><thead><tr><th>Scenario</th><th>Must cover — decision points</th></tr></thead><tbody><tr><td><strong>S3 · M02 Escalation Drill</strong><br />\n3-year-old, worsening bronchiolitis</td><td>Distress vs failure → choose device → escalate to HFNC → bag-mask\nwhen apnoeic → ISBAR handover</td></tr></tbody></table><p><b>Built so far:</b> the scenario is live in the module as a virtual simulation using the DIRECT steps (impression, intervention, reassessment, communication with parents and team, transfer). Faculty review the options and grades in the verification PDF.</p>", "webinarTitle": "Respiratory Support — \"Stridor & Wheeze; NIV & the Tracheostomised Child\" (90 min)", "webinar": "<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>Bedside differentiation</strong> of upper airway disease (stridor) from lower airway disease (wheeze). Escalation triggers and when to call for help.</li>\n<li><strong>NIV:</strong> how it helps (lower work of breathing, higher FRC, correction of hypercarbia) and why it fails, mask discomfort being the commonest cause.</li>\n<li><strong>Sedation for NIV</strong> at the course dose: dexmedetomidine 0.3–1 mcg/kg/h, on its own line and never bolused.</li>\n<li><strong>Tracheostomy care:</strong> stoma care, humidification, suctioning depth, and <strong>emergency tube change</strong> demonstrated live.</li>\n<li><strong>Breakout drill:</strong> the “Escalation Drill” case. Each step (nasal prongs → HFNC → bag-mask) is a group decision with an ISBAR call.</li>\n</ul>\n<p><strong>Good to know:</strong> heliox; tracheostomy emergency algorithms (NTSP).</p>", "downloads": [{"label": "Faculty guide · Modules 01–03 (PDF)", "href": "assets/faculty/PCCN_Faculty_Guide_M01-M03.pdf"}, {"label": "Live webinars faculty guide (PDF)", "href": "assets/faculty/PCCN_Live_Webinars_Faculty_Guide_M01-M04_M07.pdf"}, {"label": "Learner study material · Module 02 (PDF)", "href": "assets/pdf/PCCN_Module02_Study_Material.pdf"}]}, "03": {"page": "PCCN_Module03_Shock_Hemodynamics.html", "lectures": "<h3 id=\"v9-clinical-features-of-dehydration-10-min-record-by-fri-23-oct\">V9 Clinical Features of Dehydration ≤10 min · record by Fri 23 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Grading severity: no, some, or severe dehydration</p></li>\n<li><p>Bedside signs: alertness, eyes, tears, mucosa, fontanelle, skin pinch, CRT, urine output</p></li>\n<li><p>ORS Plans A, B and C, and when to switch to IV</p></li>\n<li><p>Intake–output charting and weighing</p></li>\n</ul>\n<p><strong>Good to know:</strong> dehydration with high or low sodium.</p>\n<h3 id=\"v10-types-of-shock-type-and-severity-12-min-record-by-sat-24-oct\">V10 Types of Shock — Type and Severity ≤12 min · record by Sat 24 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Hypovolaemic, distributive (septic, anaphylactic), cardiogenic, obstructive</p></li>\n<li><p>Compensated vs hypotensive shock; hypotension = SBP below 70 + (2 × age in years)</p></li>\n<li><p>Signs: heart rate, CRT, central vs peripheral pulses, mental status, urine output</p></li>\n<li><p>Warm vs cold shock at the bedside</p></li>\n</ul>\n<p><strong>Good to know:</strong> using lactate trends.</p>\n<h3 id=\"v11-fluid-resuscitation-14-min-record-by-sat-24-oct\">V11 Fluid Resuscitation ≤14 min · record by Sat 24 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>IV or IO access within 5 minutes; check glucose</p></li>\n<li><p>Bolus of 10–20 mL/kg isotonic crystalloid (smaller and slower in cardiogenic shock); push–pull technique</p></li>\n<li><p>Reassess after every bolus; signs of fluid overload (crackles, enlarging liver, rising RR)</p></li>\n<li><p>Fluid-refractory shock: when to prepare vasoactive drugs</p></li>\n</ul>\n<p><strong>Good to know:</strong> balanced crystalloids vs normal saline; when blood products are needed.</p>\n<h3 id=\"v12-nibp-how-to-choose-8-min-record-by-sun-25-oct\">V12 NIBP — How to Choose ≤8 min · record by Sun 25 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>Cuff size: bladder width about 40% of arm circumference, length 80–100%</p></li>\n<li><p>Cuff site and limb position; a cuff too small over-reads, too large under-reads</p></li>\n<li><p>How often to measure in shock; trending MAP</p></li>\n<li><p>When to move to invasive BP monitoring</p></li>\n</ul>\n<p><strong>Good to know:</strong> using Doppler for BP in small infants.</p>\n<h3 id=\"v13-the-physiologically-difficult-airway-15-min-record-by-sun-25-oct\">V13 The Physiologically Difficult Airway ≤15 min · record by Sun 25 Oct</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p>The physiological dangers of intubation: hypoxaemia, hypotension, acidosis, right-heart strain</p></li>\n<li><p>Resuscitate before you intubate: fluids, push-dose adrenaline ready, preoxygenation</p></li>\n<li><p>SOAPME checklist and the nurse’s role during intubation</p></li>\n<li><p>Watching for hypotension after intubation</p></li>\n</ul>\n<p><strong>Good to know:</strong> induction drugs that protect the haemodynamics; apnoeic oxygenation.</p>", "sims": "<p><strong>Must follow — every scenario</strong></p>\n<ul>\n<li><p>10–15 minutes long. Case stem → monitor showing vitals that change → 3–5 decision points → feedback on every choice → debrief questions.</p></li>\n<li><p>Every wrong choice shows its consequence on the monitor and a teaching line.</p></li>\n<li><p>Uses the DIRECT approach and the same vital ranges taught in the videos.</p></li>\n<li><p>Faculty provide the storyboard: one row per decision, listing options, the correct answer, the reason, and how the vitals change.</p></li>\n</ul><table><thead><tr><th>Scenario</th><th>Must cover — decision points</th></tr></thead><tbody><tr><td><strong>S4 · M03 The Septic Child</strong><br />\n6-year-old, fever, low BP, slow CRT</td><td>PAT → ABCDE → classify shock → IV/IO + bolus → reassess →\nfluid-refractory → prepare vasoactive drug</td></tr></tbody></table><p><b>Built so far:</b> the scenario is live in the module as a virtual simulation using the DIRECT steps (impression, intervention, reassessment, communication with parents and team, transfer). Faculty review the options and grades in the verification PDF.</p>", "webinarTitle": "Shock & Haemodynamics — \"The Septic Child + Fluid Calculation Workshop\" (90 min)", "webinar": "<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>The 1-hour sepsis bundle</strong>, walked through live:\n<ul>\n<li>Cultures before antibiotics.</li>\n<li>Antibiotic (ceftriaxone 100 mg/kg, max 4 g).</li>\n<li>Fluid bolus by push–pull.</li>\n<li>Vasoactive drug if fluid-refractory.</li>\n<li>Stress-dose hydrocortisone only if the child is at risk (1–2 mg/kg).</li>\n</ul></li>\n<li><strong>Calculation workshop:</strong>\n<ul>\n<li>Maintenance by the 4-2-1 rule, restricted to 50–70% while the child is sick.</li>\n<li>Deficit and replacement.</li>\n<li>Bolus volumes per kg.</li>\n<li>Peripheral adrenaline/noradrenaline infusion preparation and rate.</li>\n</ul></li>\n<li><strong>Breakout drill:</strong> each room calculates the fluids and the vasoactive infusion for a 20 kg child. A second nurse checks every calculation, and rooms swap answers to check each other.</li>\n</ul>\n<p><strong>Good to know:</strong> ROSE fluid phases; the 4 Ps before vasoactive drugs.</p>", "downloads": [{"label": "Faculty guide · Modules 01–03 (PDF)", "href": "assets/faculty/PCCN_Faculty_Guide_M01-M03.pdf"}, {"label": "Live webinars faculty guide (PDF)", "href": "assets/faculty/PCCN_Live_Webinars_Faculty_Guide_M01-M04_M07.pdf"}, {"label": "Learner study material · Module 03 (PDF)", "href": "assets/pdf/PCCN_Module03_Study_Material.pdf"}]}, "04": {"page": "PCCN_Module04_Arrhythmias_BLS_PALS.html", "lectures": "", "sims": "", "webinarTitle": "Arrhythmias, BLS & Resuscitation — \"Mega-Code Debrief\" (90 min)", "webinar": "<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>Running a code as a team:</strong>\n<ul>\n<li>A named team leader.</li>\n<li>Clear roles: compressor, airway, drugs/cart, defibrillator, recorder.</li>\n<li>Closed-loop communication.</li>\n<li>Swap compressors every 2 minutes.</li>\n</ul></li>\n<li><strong>The defibrillator under time pressure:</strong>\n<ul>\n<li>Shockable versus non-shockable rhythms.</li>\n<li>Energy 2 J/kg, then 4 J/kg (maximum 10 J/kg or the adult dose).</li>\n<li>Pad placement and a safe shock.</li>\n</ul></li>\n<li><strong>Emergency drugs at course doses:</strong>\n<ul>\n<li>Adrenaline 0.01 mg/kg (0.1 mL/kg of 1:10 000), max 1 mg.</li>\n<li>Amiodarone 5 mg/kg (max 300 mg).</li>\n<li>Adenosine 0.1 mg/kg (max 6 mg), then 0.2 mg/kg (max 12 mg).</li>\n<li>Atropine 0.02 mg/kg (max 0.5 mg).</li>\n</ul></li>\n<li><strong>Breakout drill:</strong> a timed mega-code on paper. Rooms call each action aloud with timestamps, and the facilitator scores time to first shock and pauses in CPR.</li>\n</ul>\n<p><strong>Good to know:</strong> post-cardiac-surgery JET and complete heart block; post-ROSC care.</p>", "downloads": [{"label": "Live webinars faculty guide (PDF)", "href": "assets/faculty/PCCN_Live_Webinars_Faculty_Guide_M01-M04_M07.pdf"}, {"label": "Learner study material · Module 04 (PDF)", "href": "assets/pdf/PCCN_Module04_Study_Material.pdf"}], "pending": "The lecture and simulation brief for Module 04 is in preparation. The live webinar brief is below."}, "07": {"page": "PCCN_Module.html?m=7", "lectures": "<h3 id=\"v1-neurological-assessment-avpu-paediatric-gcs-pupils-12-min\">V1 · Neurological Assessment — AVPU, Paediatric GCS &amp; Pupils (≤12 min)</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>AVPU:</strong>\n<ul>\n<li>“P” (responds only to pain) or “U” means an emergency.</li>\n<li>AVPU “P” corresponds roughly to GCS 8. Protect the airway and call for help.</li>\n</ul></li>\n<li><strong>Paediatric GCS:</strong>\n<ul>\n<li>Eye, verbal and motor scores.</li>\n<li>The modified verbal score for pre-verbal children (coos/babbles → irritable cry → cries to pain → moans to pain → none).</li>\n<li>Always report the three components, not just the total.</li>\n</ul></li>\n<li><strong>Pupils:</strong> size, equality and reaction to light. A unilateral fixed, dilated pupil is a herniation warning; tell the doctor immediately.</li>\n<li><strong>Posture and tone:</strong>\n<ul>\n<li>Decorticate (abnormal flexion) and decerebrate (abnormal extension) posturing.</li>\n<li>Flaccidity.</li>\n<li>Neck stiffness.</li>\n</ul></li>\n<li><strong>Glucose:</strong> check bedside glucose in every drowsy or seizing child. Treat hypoglycaemia at once using the course dose (section 5).</li>\n<li><strong>Late signs of raised ICP:</strong>\n<ul>\n<li>Cushing’s triad: hypertension, bradycardia, irregular breathing.</li>\n<li>These are pre-herniation signs, not early warnings.</li>\n</ul></li>\n<li><strong>Neuro observation chart:</strong> how often to record (every 15 minutes while unstable) and what change triggers escalation (a fall of 2 or more points in GCS, a new pupil change, or a new focal sign).</li>\n</ul>\n<p><strong>Good to know:</strong> FOUR score; the developmental milestones that change the verbal score; why sedation and paralysis invalidate the GCS.</p>\n<h3 id=\"v2-status-epilepticus-the-seizure-clock-14-min\">V2 · Status Epilepticus — the Seizure Clock (≤14 min)</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p><strong>Definition:</strong> a seizure lasting more than 5 minutes, or repeated seizures without recovery in between. A child brought in actively seizing is treated as status epilepticus. The ILAE time points t1 and t2 are in the table.</p>\n<table>\n<colgroup>\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Seizure type</th>\n<th>Treat by (t1)</th>\n<th>Risk of long-term harm after (t2)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Tonic–clonic</td>\n<td>5 min</td>\n<td>30 min</td>\n</tr>\n<tr class=\"even\">\n<td>Focal, impaired awareness</td>\n<td>10 min</td>\n<td>more than 60 min (ILAE; the Compendium says 30 min, so align it)</td>\n</tr>\n<tr class=\"odd\">\n<td>Absence status</td>\n<td>10–15 min</td>\n<td>not known</td>\n</tr>\n</tbody>\n</table></li>\n<li><p><strong>0–5 min, Stabilise:</strong></p>\n<ul>\n<li>Note the start time.</li>\n<li>Airway: recovery position, suction, oxygen.</li>\n<li>Attach monitoring: SpO₂ and heart rate.</li>\n<li>Check glucose.</li>\n<li>Get IV/IO access.</li>\n<li>Weigh or estimate the weight.</li>\n</ul></li>\n<li><p><strong>5–20 min, Terminate with a benzodiazepine:</strong></p>\n<ul>\n<li>Give the first dose by the fastest available route: IV/IO, or buccal or intranasal if there is no access.</li>\n<li>Give one repeat dose after 5 minutes if the seizure continues.</li>\n<li><strong>Never more than two benzodiazepine doses</strong>, counting any dose given before arrival.</li>\n</ul></li>\n<li><p><strong>20–40 min, second-line drug:</strong></p>\n<ul>\n<li>Levetiracetam, phenytoin/fosphenytoin, valproate or phenobarbitone, at the course doses.</li>\n<li>Rate of infusion, compatibility (phenytoin with saline only), and ECG/BP monitoring.</li>\n</ul></li>\n<li><p><strong>More than 40 min, refractory status:</strong></p>\n<ul>\n<li>Call the PICU or anaesthesia team for airway support and an infusion.</li>\n<li>The nurse prepares for intubation using the SOAPME checklist.</li>\n</ul></li>\n<li><p><strong>Nursing during and after the seizure:</strong></p>\n<ul>\n<li>Watch for respiratory depression after benzodiazepines.</li>\n<li>Describe the seizure: onset, side, duration, eyes, colour.</li>\n<li>Safety: nothing in the mouth, padded rails.</li>\n<li>Post-ictal observations.</li>\n<li>Keep the family informed.</li>\n</ul></li>\n<li><p><strong>Find the cause:</strong> fever, hypoglycaemia, sodium or calcium disturbance, infection, trauma, toxins, and missed antiepileptic doses.</p></li>\n</ul>\n<p><strong>Good to know:</strong> non-convulsive status and when EEG is needed; ketamine and midazolam infusions in refractory status; febrile seizure versus status.</p>\n<h3 id=\"v3-raised-icp-the-10-commandments-14-min\">V3 · Raised ICP — the 10 Commandments (≤14 min)</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><p><strong>Physiology made simple:</strong> the skull is a fixed box (Monro–Kellie), and CPP = MAP − ICP.</p>\n<ul>\n<li>Hypotension harms the brain as much as a high ICP does.</li>\n<li>Target CPP of about 40–50 mmHg according to age (Paediatric TBI guidelines 2019).</li>\n</ul></li>\n<li><p><strong>Recognition:</strong></p>\n<ul>\n<li>Early signs: headache, vomiting, irritability, a falling GCS, a bulging fontanelle.</li>\n<li>Late signs: a unilateral dilated pupil, abnormal posturing, Cushing’s triad.</li>\n</ul></li>\n<li><p><strong>The 10 commandments:</strong></p>\n<table>\n<colgroup>\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>#</th>\n<th>Commandment</th>\n<th>Target</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>1</td>\n<td>Position</td>\n<td>head midline, head end up 30°, nothing tight around the neck</td>\n</tr>\n<tr class=\"even\">\n<td>2</td>\n<td>Cluster care</td>\n<td>minimise stimulation</td>\n</tr>\n<tr class=\"odd\">\n<td>3</td>\n<td>Sedation and analgesia</td>\n<td>adequate</td>\n</tr>\n<tr class=\"even\">\n<td>4</td>\n<td>Glucose</td>\n<td>below 180 mg/dL, no hypoglycaemia</td>\n</tr>\n<tr class=\"odd\">\n<td>5</td>\n<td>Sodium</td>\n<td>145–150 mmol/L</td>\n</tr>\n<tr class=\"even\">\n<td>6</td>\n<td>PaO₂</td>\n<td>80–120 mmHg</td>\n</tr>\n<tr class=\"odd\">\n<td>7</td>\n<td>PaCO₂</td>\n<td>35–40 mmHg</td>\n</tr>\n<tr class=\"even\">\n<td>8</td>\n<td>Brief hyperventilation and 100% O₂</td>\n<td>only for signs of herniation</td>\n</tr>\n<tr class=\"odd\">\n<td>9</td>\n<td>Temperature and seizures</td>\n<td>normothermia; seizures treated aggressively</td>\n</tr>\n<tr class=\"even\">\n<td>10</td>\n<td>Hyperosmolar therapy</td>\n<td>3% saline or mannitol at the course dose</td>\n</tr>\n</tbody>\n</table></li>\n<li><p><strong>Nurse actions:</strong></p>\n<ul>\n<li>Prepare and give hyperosmolar therapy.</li>\n<li>Monitor sodium and serum osmolality (stop mannitol above 320 mOsm/kg).</li>\n<li>Keep an accurate intake–output chart.</li>\n<li>Check urine output after mannitol.</li>\n<li>Recognise and report herniation at once.</li>\n</ul></li>\n</ul>\n<p><strong>Good to know:</strong> ICP waveforms (P1/P2/P3); decompressive craniectomy nursing; suctioning technique with a raised ICP.</p>\n<h3 id=\"v4-caring-for-the-child-with-an-external-ventricular-drain-10-min\">V4 · Caring for the Child with an External Ventricular Drain (≤10 min)</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>What an EVD is and why it is used:</strong> to drain CSF and measure ICP.</li>\n<li><strong>Levelling:</strong>\n<ul>\n<li>Zero at the tragus (the level of the foramen of Monro).</li>\n<li>Re-level after every change in head or bed position.</li>\n<li>Height as prescribed (cmH₂O).</li>\n</ul></li>\n<li><strong>Clamping:</strong> clamp for repositioning, transfer, coughing or suction as the unit protocol directs. <strong>Never leave it clamped</strong> unattended.</li>\n<li><strong>Hourly chart:</strong>\n<ul>\n<li>CSF volume and colour: clear, blood-stained or cloudy.</li>\n<li>Report over-drainage or no drainage, a change in colour, and a fall in GCS.</li>\n</ul></li>\n<li><strong>Infection control:</strong>\n<ul>\n<li>Aseptic handling.</li>\n<li>Closed system, with sampling only by trained staff.</li>\n<li>Daily dressing check.</li>\n</ul></li>\n<li><strong>Recognising problems:</strong>\n<ul>\n<li>Shift and drift of the catheter (definitions as in the Compendium).</li>\n<li>Disconnection, kinking and air in the line.</li>\n<li>Signs of meningitis.</li>\n</ul></li>\n</ul>\n<p><strong>Good to know:</strong> transporting a child with an EVD; weaning trials; lumbar drains.</p>\n<h3 id=\"v5-cns-infections-acute-encephalitis-syndrome-12-min\">V5 · CNS Infections &amp; Acute Encephalitis Syndrome (≤12 min)</h3>\n<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>Recognition:</strong> fever with altered sensorium or new seizures is acute encephalitis syndrome (AES) until proven otherwise.\n<ul>\n<li>Meningitis signs: neck stiffness, bulging fontanelle, and in infants poor feeding and irritability.</li>\n<li>Rash: look for non-blanching petechiae and purpura.</li>\n</ul></li>\n<li><strong>Common causes in India:</strong>\n<ul>\n<li>Bacterial meningitis.</li>\n<li>Japanese encephalitis.</li>\n<li>Herpes simplex encephalitis.</li>\n<li>Scrub typhus.</li>\n<li>Dengue.</li>\n<li>Cerebral malaria.</li>\n</ul></li>\n<li><strong>Time-critical care:</strong>\n<ul>\n<li>ABCDE first.</li>\n<li>Blood cultures, then empirical antibiotics within 1 hour of arrival (ceftriaxone ± aciclovir at the course doses).</li>\n<li>Do not delay antibiotics for a lumbar puncture.</li>\n</ul></li>\n<li><strong>Lumbar puncture:</strong> the nurse knows the contraindications (signs of raised ICP, an unstable child, coagulopathy, local infection) and positions and monitors the child during the procedure.</li>\n<li><strong>Infection control:</strong>\n<ul>\n<li>Droplet precautions for suspected meningococcal disease for 24 hours after starting effective antibiotics.</li>\n<li>Notification as per the state programme.</li>\n</ul></li>\n<li><strong>Supportive care:</strong> seizures, fluids, sodium monitoring, fever control, glucose, and raised ICP care from V3.</li>\n</ul>\n<p><strong>Good to know:</strong> the national AES/JE programme; chemoprophylaxis for close contacts; the role of dexamethasone.</p>", "sims": "<p><strong>Must follow, for every scenario:</strong></p>\n<ul>\n<li>Use the PCCN virtual-sim framework: case, then video, then Impression, then Intervention, then response, then Reassessment, then Communication with the parents, then Team communication, then Transfer, then outcome.</li>\n<li>Every step is “choose all that apply”, graded Correct, Acceptable or Unsafe.</li>\n<li>Every unsafe choice shows its consequence on the monitor.</li>\n<li>Faculty provide a storyboard: one row per decision, listing the options, the grade of each, the reason, and how the vitals change.</li>\n</ul>\n<table>\n<colgroup>\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Scenario</th>\n<th>Case</th>\n<th>Decision points (DIRECT)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>7A · The Seizure Clock</strong></td>\n<td>3-year-old, 14 kg, brought in actively seizing for 15 min at home with fever; one dose of rectal diazepam given by the GP</td>\n<td><strong>D</strong> the child is in status epilepticus (unstable, life-threatening, neurological) → <strong>I</strong> airway, O₂, glucose and IV access, then IV midazolam or lorazepam as the <em>second and last</em> benzodiazepine → <strong>R</strong> still seizing at 10 min, so prepare levetiracetam; watch for apnoea → <strong>EC</strong> a frightened mother; time-stamped ISBAR to the doctor → <strong>T</strong> PICU after seizure control, airway protected</td>\n</tr>\n<tr class=\"even\">\n<td><strong>7B · The Unequal Pupil</strong></td>\n<td>7-year-old, 22 kg, day 2 of meningitis; GCS falls from 13 to 8, with BP 130/80, HR 62 and irregular breathing</td>\n<td><strong>D</strong> raised ICP with impending herniation (Cushing’s triad) → <strong>I</strong> head up 30° midline, O₂, call for help, prepare 3% saline or mannitol, no LP → <strong>R</strong> pupils, GCS and sodium after hyperosmolar therapy → <strong>EC</strong> honest update to the family; ISBAR to the PICU → <strong>T</strong> PICU for intubation and CT, with safe transfer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Better to follow:</strong> use a real neuro observation chart and a drug-calculation step with a dose check by a second nurse.</p>", "webinarTitle": "Neurological Emergencies — \"Neuro Night Shift: GCS Calibration & the Seizure Clock\" (90 min)", "webinar": "<p><strong>Must cover</strong></p>\n<ul>\n<li><strong>GCS calibration (0:10–0:25):</strong>\n<ul>\n<li>Three short consented clips (infant, toddler, school-age child). Every delegate scores E, V and M in a poll.</li>\n<li>Faculty reveal the agreed score, and the group discusses the common errors: verbal scoring in pre-verbal children, and best motor response versus withdrawal.</li>\n</ul></li>\n<li><strong>Seizure clock, run live (Case 1):</strong>\n<ul>\n<li>A 3-year-old is still seizing at 15 minutes after diazepam given by the GP.</li>\n<li>The moderator runs a visible timer. Delegates answer at each minute mark:\n<ul>\n<li><strong>0–5 min:</strong> stabilise and check glucose.</li>\n<li><strong>5–10 min:</strong> benzodiazepine — <strong>the second and last dose</strong>.</li>\n<li><strong>20 min:</strong> second-line drug, with the dose calculated live.</li>\n<li><strong>40 min:</strong> refractory — call the PICU, prepare with SOAPME.</li>\n</ul></li>\n</ul></li>\n<li><strong>Breakout drill — “10 commandments” cluster-care plan:</strong>\n<ul>\n<li>Each room receives a 7-year-old with meningitis and raised ICP.</li>\n<li>Each room writes the first 4 hours of nursing care, covering: position, cluster care, sedation, glucose, sodium, oxygenation, CO₂, temperature and seizures, hyperosmolar therapy, and neuro-observation frequency.</li>\n<li>The room also writes the trigger for calling the doctor (Cushing’s triad, unequal pupils).</li>\n</ul></li>\n<li><strong>Report back:</strong> one plan per room. Faculty mark against the 10 commandments, and every room fixes one gap.</li>\n<li><strong>Case 2 / demonstration:</strong>\n<ul>\n<li>EVD levelling to the tragus on camera; when to clamp.</li>\n<li>What to chart hourly and when to call.</li>\n<li>Shift and drift.</li>\n</ul></li>\n<li><strong>Communication:</strong>\n<ul>\n<li>An ISBAR call for a falling GCS, in which a delegate role-plays the call.</li>\n<li>How to talk to parents during a prolonged seizure.</li>\n</ul></li>\n</ul>\n<p><strong>Good to know:</strong> non-convulsive status; the acute encephalitis syndrome (AES) and Japanese encephalitis (JE) programmes in India.</p>\n<p><strong>Materials the faculty prepare:</strong></p>\n<ul>\n<li>3 GCS clips (consented and blurred).</li>\n<li>A seizure-clock slide with a timer.</li>\n<li>A breakout case card with an answer key.</li>\n<li>An EVD set or a photo of one.</li>\n<li>A dose sheet matching the Module 07 dose table.</li>\n</ul>", "dose": "<p>Faculty must not teach doses that differ from this table. <strong>Dr Manju Kedarnath (course director) to sign off before recording.</strong></p>\n<table>\n<colgroup>\n<col style=\"width: 25%\" />\n<col style=\"width: 25%\" />\n<col style=\"width: 25%\" />\n<col style=\"width: 25%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Drug</th>\n<th>Dose</th>\n<th>Maximum</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Midazolam, buccal or intranasal</td>\n<td>0.3 mg/kg (buccal) · 0.2 mg/kg (intranasal)</td>\n<td>10 mg</td>\n<td>When there is no IV/IO access</td>\n</tr>\n<tr class=\"even\">\n<td>Midazolam IV/IO</td>\n<td>0.15 mg/kg</td>\n<td>7.5 mg</td>\n<td>Repeat once after 5 min if needed</td>\n</tr>\n<tr class=\"odd\">\n<td>Lorazepam IV/IO</td>\n<td>0.1 mg/kg</td>\n<td>4 mg</td>\n<td>Repeat once after 5 min if needed</td>\n</tr>\n<tr class=\"even\">\n<td>Diazepam IV / rectal</td>\n<td>0.2–0.3 mg/kg IV · 0.5 mg/kg rectal</td>\n<td>10 mg IV · 20 mg rectal</td>\n<td></td>\n</tr>\n<tr class=\"odd\">\n<td>Levetiracetam IV</td>\n<td>40–60 mg/kg over 5–15 min</td>\n<td>3000–4500 mg (protocol)</td>\n<td>Second line</td>\n</tr>\n<tr class=\"even\">\n<td>Phenytoin IV</td>\n<td>20 mg/kg over 20 min</td>\n<td>1500 mg</td>\n<td>Saline only; ECG and BP monitoring</td>\n</tr>\n<tr class=\"odd\">\n<td>Fosphenytoin IV</td>\n<td>20 mg PE/kg</td>\n<td>1500 mg PE</td>\n<td></td>\n</tr>\n<tr class=\"even\">\n<td>Sodium valproate IV</td>\n<td>40 mg/kg over 5–10 min</td>\n<td>3000 mg</td>\n<td>Avoid under 2 years and in suspected metabolic or liver disease</td>\n</tr>\n<tr class=\"odd\">\n<td>Phenobarbitone IV</td>\n<td>20 mg/kg over 20 min</td>\n<td>1000 mg</td>\n<td>Watch for respiratory depression and hypotension</td>\n</tr>\n<tr class=\"even\">\n<td>3% sodium chloride</td>\n<td>3–5 mL/kg over 10–20 min</td>\n<td>—</td>\n<td>Raised ICP / herniation</td>\n</tr>\n<tr class=\"odd\">\n<td>Mannitol 20%</td>\n<td>0.5–1 g/kg (2.5–5 mL/kg) over 20 min</td>\n<td>—</td>\n<td>Stop if osmolality is above 320 mOsm/kg</td>\n</tr>\n<tr class=\"even\">\n<td>10% dextrose (hypoglycaemia)</td>\n<td><strong>Course to choose one:</strong> 2 mL/kg (APLS, used in Modules 01–03) <strong>or</strong> 10 mL/kg (Compendium Section 5)</td>\n<td>—</td>\n<td>Recheck glucose in 15 min</td>\n</tr>\n<tr class=\"odd\">\n<td>Ceftriaxone IV</td>\n<td>100 mg/kg/day in 1–2 doses (meningitis)</td>\n<td>4 g/day</td>\n<td>Within 1 hour</td>\n</tr>\n<tr class=\"even\">\n<td>Aciclovir IV</td>\n<td>20 mg/kg 8-hourly (under 3 months) · 10–15 mg/kg 8-hourly (older)</td>\n<td>per protocol</td>\n<td>Suspected HSV encephalitis</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Flag for the course director:</strong> the Compendium’s 10% dextrose dose (10 mL/kg) differs from the dose already used in Modules 01–03 (2 mL/kg, APLS). Choose one dose for the whole course before scripts are written.</p>", "lab": "<table>\n<colgroup>\n<col style=\"width: 50%\" />\n<col style=\"width: 50%\" />\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Station</th>\n<th>Content</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Neuro assessment OSCE</td>\n<td>AVPU and paediatric GCS on a simulated infant and child, pupils, and neuro chart entry</td>\n</tr>\n<tr class=\"even\">\n<td>Seizure management drill</td>\n<td>Seizure clock in real time: recovery position, suction, buccal midazolam draw-up, second-line drug calculation</td>\n</tr>\n<tr class=\"odd\">\n<td>EVD care</td>\n<td>Levelling to the tragus, clamping and unclamping, hourly chart, sterile sampling (demonstration)</td>\n</tr>\n<tr class=\"even\">\n<td>Cluster-care planning</td>\n<td>Group activity: plan 24 hours of care for a child with raised ICP</td>\n</tr>\n</tbody>\n</table>", "downloads": [{"label": "Faculty guide · Module 07 Neurological Emergencies (PDF)", "href": "assets/faculty/PCCN_Module07_Neuro_Emergencies_Faculty_Guide.pdf"}, {"label": "Live webinars faculty guide (PDF)", "href": "assets/faculty/PCCN_Live_Webinars_Faculty_Guide_M01-M04_M07.pdf"}]}};
